files.lib_test.go:
package kit

import (
	"fmt"
	"testing"
)

// Adding two numbers gives their sum.
func ExampleAdd() {
	fmt.Println(Add(1, 2))
	// Output: 3
}

func TestAdd(t *testing.T) {
	if Add(1, 2) != 3 {
		t.Fatal("1 + 2 is not 3")
	}
}

func BenchmarkAdd(b *testing.B) {
	for i := 0; i < b.N; i++ {
		Add(1, 2)
	}
}

