// Package docs holds the runners of the tables on the pages.
package docs

import (
	"fmt"
	"strconv"

	"example.com/kit"
)

// Cases are the runners of cases tables, by name.
var Cases = map[string]func(row map[string]string) error{
	"adds": adds,
}

func adds(row map[string]string) error {
	a, _ := strconv.Atoi(row["a"])
	b, _ := strconv.Atoi(row["b"])
	if got := strconv.Itoa(kit.Add(a, b)); got != row["sum"] {
		return fmt.Errorf("expected %s, got %s", row["sum"], got)
	}
	return nil
}

